const MOTION=Object.freeze({micro:parseFloat(motionStyle.getPropertyValue('--motion-micro'))||150,normal:parseFloat(motionStyle.getPropertyValue('--motion-normal'))||260,major:parseFloat(motionStyle.getPropertyValue('--motion-major'))||650,signal:140,stagger:45,entrance:220,exit:180,bridgeLead:250,focus:320,ease:motionStyle.getPropertyValue('--motion-ease').trim()||'cubic-bezier(0.22, 1, 0.36, 1)'});
