function motion(el,frames,options={}){if(!el)return Promise.resolve();const {hold=false,...timing}=options;const animation=el.animate(frames,{duration:reduced?1:MOTION.normal,easing:MOTION.ease,fill:'both',...timing,...(reduced?{duration:1,delay:0}:{})});return animation.finished.catch(()=>{}).finally(()=>{if(!hold)animation.cancel();});}
function pulse(el){if(!el)return;feedbackAnimations.get(el)?.cancel();const a=el.animate([{transform:'scale(1)',boxShadow:'inset 0 0 0 999px transparent'},{transform:'scale(.965)',boxShadow:'inset 0 0 0 999px rgba(187,25,25,.22)',offset:.22},{transform:'scale(1)',boxShadow:'inset 0 0 0 999px transparent'}],{duration:reduced?1:MOTION.normal,easing:MOTION.ease});feedbackAnimations.set(el,a);a.finished.catch(()=>{});}
function feedback(command){const selectors={prev:'#prev,[data-hint="prev"],[data-action="prev"]',next:'#next,[data-hint="next"],[data-action="next"]',enter:'[data-hint="enter"],[data-action="advance"]',guide:'#guideBtn,[data-action="guide"]',pause:'#pauseBtn,[data-action="pause"]',mute:'#muteBtn',fullscreen:'#fullscreen',lens:'[data-action="lens"]',direct:'[data-hint="direct"]'};document.querySelectorAll(selectors[command]||'__none__').forEach(pulse);}
async function panel(el,visible){const version=(panelVersions.get(el)||0)+1;panelVersions.set(el,version);el.getAnimations().forEach(a=>a.cancel());if(visible){el.hidden=false;el.inert=false;await motion(el,[{opacity:0,transform:'translateY(8px) scale(.99)'},{opacity:1,transform:'none'}]);}else{if(el.hidden)return;el.inert=true;await motion(el,[{opacity:getComputedStyle(el).opacity,transform:'none'},{opacity:0,transform:'translateY(6px) scale(.99)'}],{duration:MOTION.micro});if(panelVersions.get(el)===version)el.hidden=true;}}
function revealCopy(el,delay=0){if(!el)return;el.getAnimations().filter(a=>!(a instanceof CSSAnimation)).forEach(a=>a.cancel());if(paused||(lensOpen&&current===5)||reduced)return;motion(el,[{opacity:0,transform:'translateY(9px)'},{opacity:1,transform:'none'}],{duration:MOTION.normal,delay});}
function enterChannel(){if(current<5){VideoDeck.resume(true);return Promise.all([motion($('.show-film'),[{opacity:.35,transform:'scale(1.025)'},{opacity:1,transform:'scale(1)'}],{duration:550}),motion($('.show-top'),[{opacity:0},{opacity:1}],{duration:320,delay:100})]);}return Promise.all(['.bug','#headline','#bodycopy','.error-checks','.topic-strip'].map((sel,i)=>motion($(sel),[{opacity:0,translate:'0 8px'},{opacity:1,translate:'0 0'}],{duration:220,delay:i*45})));}

