function selectProgramme(index,notify=true){selected=(index+6)%6;const guideEl=$('.guide');if(!guideEl)return;guideEl.querySelectorAll('.tile').forEach((el,i)=>{el.classList.toggle('selected',i===selected);el.setAttribute('aria-pressed',String(i===selected));});guideEl.querySelectorAll('[data-home-channel]').forEach(el=>el.classList.toggle('active',Number(el.dataset.homeChannel)===selected));const f=HOME_FEATURES[selected];if(VideoDeck.pool[selected])VideoDeck.pool[selected].preload='auto';$('#homeHeadline').innerHTML=f[0];$('#homeSummary').textContent=f[1];$('#homeCategory').textContent=`CH ${String(selected+1).padStart(2,'0')} / ${f[2].toUpperCase()}`;$('#homeWatch').innerHTML=`<span aria-hidden="true">▶</span> Watch ${f[2]} <kbd>↵</kbd>`;const art=$('.home-hero-art');const photos=[...art.querySelectorAll('.hero-photo')];const old=photos.pop();photos.forEach(el=>el.remove());if(f[4]){const next=document.createElement('img');next.className='hero-photo';next.src=MEDIA_ROOT+'images/'+f[4]+'.jpg';next.alt='';next.decoding='async';art.append(next);if(old)motion(next,[{opacity:0},{opacity:1}],{duration:360}).then(()=>old.remove());}else{art.querySelectorAll('img').forEach(el=>el.remove());}art.classList.toggle('hero-no-signal',!f[4]);const tile=guideEl.querySelector(`[data-channel="${selected}"]`);if(document.activeElement?.matches('.guide .tile')&&document.activeElement!==tile)tile.focus({preventScroll:true});if(notify){revealCopy($('#homeHeadline'));revealCopy($('#homeSummary'),45);announce(`Selected channel ${selected+1}, ${channels[selected].name}`);}}

function stageRect(el){const a=el.getBoundingClientRect(),b=$('#screen').getBoundingClientRect(),scale=b.width/1440;return{x:(a.left-b.left)/scale,y:(a.top-b.top)/scale,w:a.width/scale,h:a.height/scale};}
function layerClone(el){const clone=el.cloneNode(true);const originals=el.querySelectorAll('video');clone.querySelectorAll('video').forEach((v,i)=>{const original=originals[i],c=document.createElement('canvas');c.className=v.className;c.width=original.videoWidth||1280;c.height=original.videoHeight||720;try{c.getContext('2d').drawImage(original,0,0,c.width,c.height);v.replaceWith(c);}catch{v.removeAttribute('src');v.load();}});clone.removeAttribute('id');clone.querySelectorAll('[id]').forEach(n=>n.removeAttribute('id'));clone.querySelectorAll('button,a,input').forEach(n=>n.tabIndex=-1);clone.setAttribute('aria-hidden','true');clone.inert=true;clone.classList.add('motion-layer');$('#screen').append(clone);return clone;}
