function referenceUI(){if(mode!=='channel'||current>4||!VideoDeck.active)return;const v=VideoDeck.active,show=$('.show-preview'),duration=VideoDeck.full?(Number.isFinite(v.duration)?v.duration:0):60;show?.classList.toggle('preview-watching',v.currentTime>=5&&!VideoDeck.finished);const fraction=duration?Math.min(1,v.currentTime/duration):0;const progress=$('#showProgress');if(progress)progress.style.transform=`scaleX(${fraction})`;if($('#showSeek')&&document.activeElement!==$('#showSeek'))$('#showSeek').value=String(fraction*100);const seconds=Math.floor(v.currentTime);if(seconds!==referenceUI.lastSecond){referenceUI.lastSecond=seconds;const fmt=n=>`${Math.floor(n/60)}:${String(Math.floor(n)%60).padStart(2,'0')}`;$('#showTime').textContent=`${fmt(seconds)} / ${fmt(duration)}`;}}

