function ensureAudio(){try{if(!audioCtx){audioCtx=new (window.AudioContext||window.webkitAudioContext)();master=audioCtx.createGain();master.connect(audioCtx.destination);staticSound=audioCtx.createBuffer(1,Math.floor(audioCtx.sampleRate*.14),audioCtx.sampleRate);const samples=staticSound.getChannelData(0);for(let i=0;i<samples.length;i++)samples[i]=(Math.random()*2-1)*.13;}if(audioCtx.state==='suspended')audioCtx.resume();master.gain.setTargetAtTime(muted?0:volume*.28,audioCtx.currentTime,.03);}catch(e){$('#muteBtn').textContent='SOUND UNAVAILABLE';}}
function tone(freq,duration=.12,type='sine',delay=0){if(!audioCtx||muted)return;const t=audioCtx.currentTime+delay,o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.3,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(master);o.start(t);o.stop(t+duration+.02);}
